mapper.select:
SELECT * FROM v_student_course_schedule
WHERE student_id = #{studentId}
AND semester_id = #{semesterId}
ORDER BY weekday, start_section

SELECT * FROM v_teacher_course_roster
WHERE teacher_id = #{teacherId}
AND teaching_class_id = #{teachingClassId}
ORDER BY teaching_class_code, student_no

SELECT * FROM v_course_grade_statistics
WHERE course_id = #{courseId}
ORDER BY course_code, teaching_class_code
